import { useState } from "react";
import axios from "axios";

export default function Cadastro() {
  const [form, setForm] = useState({
    nome: "",
    idade: "",
    rua: "",
    bairro: "",
    estado: "",
    biografia: "",
  });
  const [imagem, setImagem] = useState(null);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleImagemChange = (e) => {
    setImagem(e.target.files[0]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    Object.entries(form).forEach(([key, value]) => {
      formData.append(key, value);
    });
    formData.append("imagem", imagem);

    try {
      await axios.post("http://localhost:3001/usuarios", formData);
      alert("Usuário cadastrado com sucesso!");
      window.location.href = "/perfil";

    } catch (err) {
      console.error("Erro ao cadastrar:", err);
      alert("Erro ao cadastrar.");
    }
  };

  return (
    <form onSubmit={handleSubmit} encType="multipart/form-data">
      <input name="nome" placeholder="Nome" onChange={handleChange} required />
      <input name="idade" placeholder="Idade" onChange={handleChange} required />
      <input name="rua" placeholder="Rua" onChange={handleChange} required />
      <input name="bairro" placeholder="Bairro" onChange={handleChange} required />
      <input name="estado" placeholder="Estado" onChange={handleChange} required />
      <textarea name="biografia" placeholder="Biografia" onChange={handleChange} required />
      <input type="file" name="imagem" onChange={handleImagemChange} required />
      <button type="submit">Cadastrar</button>
    </form>
  );
}
